package processor

import (
	"errors"

	"github.com/devicechain-io/dc-microservice/credential"
)

// IntegrationPolicies is the one kind inbound integration authentication compares,
// Unthrottled: the token is generated by the server from 256 random bits, so a per-key backoff
// buys no guessing resistance and would hand anyone who knows an integration's slug a way to
// lock the sender out of its own integration. A flood of bad tokens is bounded where the
// requests arrive (a per-integration failure bucket on the ingest path), not here.
//
// credential.NewChecker refuses the kind with any other policy.
var IntegrationPolicies = map[credential.Kind]credential.Policy{
	credential.KindIntegration: {Unthrottled: true},
}

// NewIntegrationChecker builds the Checker inbound integration authentication compares
// through. main.go calls this and nothing else, and the model's AuthenticateIntegration reads
// its tokens through it.
//
// 🔴 THE KEY IS A PARAMETER, NOT AN OPTION, and it is the SAME value the Api digests with
// (Api.EnrollmentKeys.Integration). A digest written under one key verifies only under that
// key: a Checker handed another key would refuse every integration in the instance. The
// wiring test over this function writes a digest through the Api and verifies it through the
// Checker main.go builds.
//
// The kind is Unthrottled and never reads or writes an attempt record, so the store it is
// given is one that FAILS every call: if a later change made the kind throttled the Checker
// would refuse construction (ErrMustBeUnthrottled), and if anything reached the store anyway
// the attempt would error rather than silently count in a bucket it was not meant for.
func NewIntegrationChecker(enrollment *credential.EnrollmentSecretKeys, opts ...credential.Option) (*credential.Checker, error) {
	if enrollment == nil || enrollment.Integration == nil {
		return nil, errors.New("an integration checker needs the integration secret key")
	}
	return credential.NewChecker(unusedAttemptStore{}, IntegrationPolicies, append([]credential.Option{
		credential.WithIntegrationSecretKey(enrollment.Integration),
	}, opts...)...)
}
